'use client';

import { useTheme } from './theme-provider';
import type { ThemePreference } from '@/lib/theme';

/* Liquid-glass SVG filter recipe kept verbatim (feImage displacement map ->
   feGaussianBlur -> feDisplacementMap) — this component exists to test that
   effect on the real toggle, not a redesign, so the filter data itself is
   untouched. Two nearly-identical filters, differing only in blur amount:
   one for the pill's backdrop, one for the sliding thumb. */
const DISPLACEMENT_MAP =
  'data:image/png;base64,';

type PrefOption = { value: ThemePreference; label: string; icon: React.ReactNode };

const OPTIONS: PrefOption[] = [
  {
    value: 'light',
    label: 'Light',
    icon: (
      <svg className="ls-switcher__icon" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 36 36">
        <path
          fill="var(--c)"
          fillRule="evenodd"
          d="M18 12a6 6 0 1 1 0 12 6 6 0 0 1 0-12Zm0 2a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"
          clipRule="evenodd"
        />
        <path
          fill="var(--c)"
          d="M17 6.038a1 1 0 1 1 2 0v3a1 1 0 0 1-2 0v-3ZM24.244 7.742a1 1 0 1 1 1.618 1.176L24.1 11.345a1 1 0 1 1-1.618-1.176l1.763-2.427ZM29.104 13.379a1 1 0 0 1 .618 1.902l-2.854.927a1 1 0 1 1-.618-1.902l2.854-.927ZM29.722 20.795a1 1 0 0 1-.619 1.902l-2.853-.927a1 1 0 1 1 .618-1.902l2.854.927ZM25.862 27.159a1 1 0 0 1-1.618 1.175l-1.763-2.427a1 1 0 1 1 1.618-1.175l1.763 2.427ZM19 30.038a1 1 0 0 1-2 0v-3a1 1 0 1 1 2 0v3ZM11.755 28.334a1 1 0 0 1-1.618-1.175l1.764-2.427a1 1 0 1 1 1.618 1.175l-1.764 2.427ZM6.896 22.697a1 1 0 1 1-.618-1.902l2.853-.927a1 1 0 1 1 .618 1.902l-2.853.927ZM6.278 15.28a1 1 0 1 1 .618-1.901l2.853.927a1 1 0 1 1-.618 1.902l-2.853-.927ZM10.137 8.918a1 1 0 0 1 1.618-1.176l1.764 2.427a1 1 0 0 1-1.618 1.176l-1.764-2.427Z"
        />
      </svg>
    ),
  },
  {
    value: 'dark',
    label: 'Dark',
    icon: (
      <svg className="ls-switcher__icon" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 36 36">
        <path
          fill="var(--c)"
          d="M12.5 8.473a10.968 10.968 0 0 1 8.785-.97 7.435 7.435 0 0 0-3.737 4.672l-.09.373A7.454 7.454 0 0 0 28.732 20.4a10.97 10.97 0 0 1-5.232 7.125l-.497.27c-5.014 2.566-11.175.916-14.234-3.813l-.295-.483C5.53 18.403 7.13 11.93 12.017 8.77l.483-.297Zm4.234.616a8.946 8.946 0 0 0-2.805.883l-.429.234A9 9 0 0 0 10.206 22.5l.241.395A9 9 0 0 0 22.5 25.794l.416-.255a8.94 8.94 0 0 0 2.167-1.99 9.433 9.433 0 0 1-2.782-.313c-5.043-1.352-8.036-6.535-6.686-11.578l.147-.491c.242-.745.573-1.44.972-2.078Z"
        />
      </svg>
    ),
  },
  {
    value: 'system',
    label: 'System',
    icon: (
      <svg className="ls-switcher__icon" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 36 36">
        <path
          fill="var(--c)"
          fillRule="evenodd"
          d="M5 8a2 2 0 0 1 2-2h22a2 2 0 0 1 2 2v15a2 2 0 0 1-2 2h-8.2l.6 3H24a1 1 0 1 1 0 2H12a1 1 0 1 1 0-2h2.6l.6-3H7a2 2 0 0 1-2-2V8Zm2 0h22v15H7V8Z"
          clipRule="evenodd"
        />
      </svg>
    ),
  },
];

const KEYFRAME_BY_INDEX = ['ls-scale-1', 'ls-scale-2', 'ls-scale-3'];

export function ThemeSwitcher() {
  const { preference, setPreference } = useTheme();
  const activeIndex = OPTIONS.findIndex((o) => o.value === preference);

  return (
    <fieldset className="ls-switcher" style={{ '--i': activeIndex } as React.CSSProperties}>
      <legend className="ls-switcher__legend">Choose theme</legend>

      {OPTIONS.map((option) => (
        <label key={option.value} className="ls-switcher__option">
          <input
            className="ls-switcher__input"
            type="radio"
            name="ls-theme"
            value={option.value}
            checked={preference === option.value}
            onChange={() => setPreference(option.value)}
          />
          {option.icon}
        </label>
      ))}

      <span
        className="ls-switcher__thumb"
        style={{ animationName: KEYFRAME_BY_INDEX[activeIndex] } as React.CSSProperties}
        aria-hidden="true"
      />

      <div className="ls-switcher__filter">
        <svg>
          <filter id="ls-switcher" primitiveUnits="objectBoundingBox">
            <feImage result="map" width="100%" height="100%" x="0" y="0" href={DISPLACEMENT_MAP} />
            <feGaussianBlur in="SourceGraphic" stdDeviation="0.04" result="blur" />
            <feDisplacementMap in="blur" in2="map" scale="0.5" xChannelSelector="R" yChannelSelector="G" />
          </filter>
          <filter id="ls-toggler" primitiveUnits="objectBoundingBox">
            <feImage result="map" width="100%" height="100%" x="0" y="0" href={DISPLACEMENT_MAP} />
            <feGaussianBlur in="SourceGraphic" stdDeviation="0.01" result="blur" />
            <feDisplacementMap in="blur" in2="map" scale="0.5" xChannelSelector="R" yChannelSelector="G" />
          </filter>
        </svg>
      </div>
    </fieldset>
  );
}
